// Ошибка кэша стадий (`M-05`).
//
// ОШИБКА НАЗЫВАЕТ ПРАВИЛО, А НЕ СЛЕДСТВИЕ — то же решение, что у `AssembleError` (`M-04`),
// `AudioError` (`M-03`) и `VoiceError` (`V-01`). Кэш — главный источник ТИХИХ ошибок
// (ADR-0006 Context: «валидный по ключу, но неверный артефакт» обнаруживается на телефоне,
// а не в тестах), поэтому каждая ошибка здесь обязана называть строку реестра или пункт ADR,
// по которому её искать.

/** Правила, на которые ссылаются ошибки кэша. */
export type CacheRule =
  /** **K1**: поле в `cacheKeyView` ⇒ ключ меняется; поле вне ⇒ не меняется. */
  | 'K1'
  /** **K2**: `cacheKeyView` — литеральные данные в репозитории, а не код. */
  | 'K2'
  /** **K3**: попадание кэша == промах кэша. */
  | 'K3'
  /** **K7**: запись атомарна (`tmp + fsync + rename`). */
  | 'K7'
  /** ADR-0006 §2: формулы ключей и инъективная каноническая форма их входа. */
  | 'ADR-0006 §2'
  /** ADR-0006 §8: манифест, проверка на попадании, атомарность. */
  | 'ADR-0006 §8'
  /** ADR-0006 §13: пространства имён по `profileId`; `.store` не подлежит GC. */
  | 'ADR-0006 §13';

/** Нарушение правила кэша: несёт имя правила, а не только текст. */
export class CacheError extends RangeError {
  readonly rule: CacheRule;

  constructor(rule: CacheRule, reason: string) {
    super(`${rule}: ${reason}`);
    this.name = 'CacheError';
    this.rule = rule;
  }
}
